47	diff --git a/src/explore/drive/collide.ts b/src/explore/drive/collide.ts
48	new file mode 100644
49	index 0000000..bedec7f
50	--- /dev/null
51	+++ b/src/explore/drive/collide.ts
52	@@ -0,0 +1,195 @@
53	+/* ============================ Lái xe: va chạm thân xe nhiều tầng ============================
54	+   Thân xe là hình chữ nhật có hướng (dài × rộng VF 3), tâm ở giữa hai trục bánh, cao độ p.y là mặt đường tại tâm.
55	+   - Thân xe hợp lệ khi 9 điểm mẫu (4 góc, 4 trung điểm cạnh, tâm) đều có mặt đường cùng tầng (drGround hữu hạn từ yRef = p.y),
56	+     không chồng vật cản nào có khoảng cao độ giao [y + sim.floor, y + chiều cao xe], không chồng hộp xe tự động cùng tầng (trừ hộp bỏ qua).
57	+   - Luật xe tự động (spec §6): đầu mỗi drMove, hộp nào đã chồng tư thế xuất phát thì bỏ qua cả lượt đó; nhờ vậy xe tự động đâm tới
58	+     thì đi xuyên, người chơi tự lao vào thì bị chặn, đã chồng thì vẫn lái ra được theo mọi hướng.
59	+   - Vật cản tra qua chỉ mục lưới ô DRC m (mẫu stroll/map.ts), giữ ngoài DrNet trong một WeakMap; dựng lười, nối thêm khi drAddSolids
60	+     push vật cản mới, dựng lại khi mảng bị thay. Vật cản phủ quá nhiều ô để riêng danh sách "lớn", tra tuyến tính.
61	+   - drFits / drMove / drSegClear chạy mỗi khung: không cấp phát (D-018), trừ khi lưới nối thêm vật cản hoặc mảng bỏ qua phải nới.
62	+   Quy ước hướng: yaw = 0 mũi xe hướng +X; vectơ tiến (cos yaw, −sin yaw); dyaw > 0 là rẽ trái khi tiến. */
63	+import { CONFIG } from '../../config';
64	+import { drGround, type DrNet, type DrSolid } from './net';
65	+
66	+export interface DrPose { x: number; y: number; z: number; yaw: number }
67	+export interface DrBox { x: number; y: number; z: number; yaw: number; hl: number; hw: number }   // hộp xe tự động: nửa dài, nửa rộng
68	+
69	+const CAR = CONFIG.drive.car, SIM = CONFIG.drive.sim;
70	+const HL = CAR.length / 2, HW = CAR.width / 2;                       // nửa dài, nửa rộng thân xe, m
71	+const AX = CAR.wheelbase / 2;                                        // tâm → trục sau, m
72	+const REACH = AX + Math.hypot(HL, HW);                               // trục sau → góc xe xa nhất: quãng góc xe quét khi xoay dyaw là ≤ REACH · |dyaw|
73	+const EPS = 1e-9;
74	+
75	+/* ===== Chỉ mục lưới vật cản ===== */
76	+const DRC = 16;          // cạnh ô lưới, m
77	+const DR_BIG = 64;       // vật cản phủ hơn số ô này thì vào danh sách "lớn"
78	+const DR_OFF = 32768;    // dời chỉ số ô về số dương để ghép khóa (±524 km)
79	+const drKey = (ix: number, iz: number): number => (ix + DR_OFF) * 65536 + (iz + DR_OFF);
80	+interface DrGrid { arr: DrSolid[]; n: number; cells: Map<number, number[]>; big: number[] }
81	+const GRIDS = new WeakMap<DrNet, DrGrid>();
82	+
83	+function drIndexOne(g: DrGrid, s: DrSolid, i: number): void {
84	+  const c = s.kind === 'circle';
85	+  const x0 = c ? s.cx - s.r : s.x0, x1 = c ? s.cx + s.r : s.x1, z0 = c ? s.cz - s.r : s.z0, z1 = c ? s.cz + s.r : s.z1;
86	+  const ix0 = Math.floor(x0 / DRC), ix1 = Math.floor(x1 / DRC), iz0 = Math.floor(z0 / DRC), iz1 = Math.floor(z1 / DRC);
87	+  if ((ix1 - ix0 + 1) * (iz1 - iz0 + 1) > DR_BIG) { g.big.push(i); return; }
88	+  for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
89	+    const k = drKey(ix, iz); let list = g.cells.get(k);
90	+    if (!list) { list = []; g.cells.set(k, list); }
91	+    list.push(i);
92	+  }
93	+}
94	+/* Lưới của net, cập nhật theo net.solids (drAddSolids chỉ push nên chỉ nối phần mới) */
95	+function drGrid(net: DrNet): DrGrid {
96	+  let g = GRIDS.get(net);
97	+  if (!g || g.arr !== net.solids || g.n > net.solids.length) { g = { arr: net.solids, n: 0, cells: new Map(), big: [] }; GRIDS.set(net, g); }
98	+  while (g.n < net.solids.length) { drIndexOne(g, net.solids[g.n], g.n); g.n++; }
99	+  return g;
100	+}
101	+
102	+/* ===== Hình học ===== */
103	+/* Thân xe (tâm x, z; cos c, sin s) chồng vật cản sol không (chỉ mặt bằng). Trục tiến f = (c, −s), trục ngang n = (s, c) */
104	+function drHitSolid(sol: DrSolid, x: number, z: number, c: number, s: number): boolean {
105	+  const ac = Math.abs(c), as = Math.abs(s);
106	+  if (sol.kind === 'circle') {
107	+    const dx = sol.cx - x, dz = sol.cz - z;
108	+    let lf = dx * c - dz * s, ln = dx * s + dz * c;                   // tâm tròn trong hệ thân xe
109	+    lf = lf > HL ? HL : lf < -HL ? -HL : lf; ln = ln > HW ? HW : ln < -HW ? -HW : ln;
110	+    const ex = x + lf * c + ln * s - sol.cx, ez = z - lf * s + ln * c - sol.cz;
111	+    return ex * ex + ez * ez < sol.r * sol.r - EPS;
112	+  }
113	+  const ex = (sol.x1 - sol.x0) / 2, ez = (sol.z1 - sol.z0) / 2, dx = (sol.x0 + sol.x1) / 2 - x, dz = (sol.z0 + sol.z1) / 2 - z;
114	+  if (Math.abs(dx) >= ex + HL * ac + HW * as - EPS) return false;    // tách theo trục X
115	+  if (Math.abs(dz) >= ez + HL * as + HW * ac - EPS) return false;    // trục Z
116	+  if (Math.abs(dx * c - dz * s) >= HL + ex * ac + ez * as - EPS) return false;   // trục tiến
117	+  if (Math.abs(dx * s + dz * c) >= HW + ex * as + ez * ac - EPS) return false;   // trục ngang
118	+  return true;
119	+}
120	+/* Thân xe chồng hộp xe tự động b không (cùng tầng: chân hai xe chênh < chiều cao xe) */
121	+function drHitBox(b: DrBox, x: number, y: number, z: number, c: number, s: number): boolean {
122	+  if (Math.abs(b.y - y) >= CAR.height) return false;
123	+  const bc = Math.cos(b.yaw), bs = Math.sin(b.yaw), dx = b.x - x, dz = b.z - z;
124	+  /* bốn trục tách: f1 = (c, −s), n1 = (s, c), f2 = (bc, −bs), n2 = (bs, bc); hình chiếu nửa hộp lên trục a là hl|f·a| + hw|n·a| */
125	+  const ff = c * bc + s * bs, fn = c * bs - s * bc;                  // f1·f2, f1·n2
126	+  const nf = s * bc - c * bs, nn = s * bs + c * bc;                  // n1·f2, n1·n2
127	+  if (Math.abs(dx * c - dz * s) >= HL + b.hl * Math.abs(ff) + b.hw * Math.abs(fn) - EPS) return false;
128	+  if (Math.abs(dx * s + dz * c) >= HW + b.hl * Math.abs(nf) + b.hw * Math.abs(nn) - EPS) return false;
129	+  if (Math.abs(dx * bc - dz * bs) >= b.hl + HL * Math.abs(ff) + HW * Math.abs(nf) - EPS) return false;
130	+  if (Math.abs(dx * bs + dz * bc) >= b.hw + HL * Math.abs(fn) + HW * Math.abs(nn) - EPS) return false;
131	+  return true;
132	+}
133	+
134	+/* ===== Thân xe hợp lệ ===== */
135	+export function drFits(net: DrNet, p: DrPose, boxes: DrBox[], nBoxes: number, ignore: Uint8Array): boolean {
136	+  const yRef = p.y, c = Math.cos(p.yaw), s = Math.sin(p.yaw);
137	+  for (let i = -1; i <= 1; i++) for (let j = -1; j <= 1; j++) {
138	+    const lf = i * HL, ln = j * HW;
139	+    if (Number.isNaN(drGround(net, p.x + lf * c + ln * s, p.z - lf * s + ln * c, yRef))) return false;
140	+  }
141	+  const ya = yRef + SIM.floor, yb = yRef + CAR.height, sol = net.solids, g = drGrid(net);
142	+  const big = g.big;
143	+  for (let i = 0; i < big.length; i++) { const o = sol[big[i]]; if (o.y1 > ya && o.y0 < yb && drHitSolid(o, p.x, p.z, c, s)) return false; }
144	+  const R = HL * Math.abs(c) + HW * Math.abs(s), Rz = HL * Math.abs(s) + HW * Math.abs(c);   // nửa khung bao thân xe theo X, Z
145	+  const ix0 = Math.floor((p.x - R) / DRC), ix1 = Math.floor((p.x + R) / DRC), iz0 = Math.floor((p.z - Rz) / DRC), iz1 = Math.floor((p.z + Rz) / DRC);
146	+  for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
147	+    const list = g.cells.get(drKey(ix, iz));
148	+    if (!list) continue;
149	+    for (let i = 0; i < list.length; i++) { const o = sol[list[i]]; if (o.y1 > ya && o.y0 < yb && drHitSolid(o, p.x, p.z, c, s)) return false; }
150	+  }
151	+  for (let i = 0; i < nBoxes; i++) if (!ignore[i] && drHitBox(boxes[i], p.x, yRef, p.z, c, s)) return false;
152	+  return true;
153	+}
154	+
155	+/* ===== Dời thân xe ===== */
156	+let IGN = new Uint8Array(16);                                        // hộp bỏ qua trong lượt drMove hiện tại
157	+const CUR: DrPose = { x: 0, y: 0, z: 0, yaw: 0 }, CAND: DrPose = { x: 0, y: 0, z: 0, yaw: 0 };
158	+let mNet: DrNet, mBoxes: DrBox[], mN = 0;                            // tham số của lượt drMove hiện tại (tránh truyền lại / tạo closure)
159	+
160	+/* Thử đặt thân xe tại CAND (cao độ lấy lại theo mặt đường tại tâm); được thì chép sang CUR */
161	+function drTry(): boolean {
162	+  const y = drGround(mNet, CAND.x, CAND.z, CUR.y);
163	+  if (Number.isNaN(y)) return false;
164	+  CAND.y = y;
165	+  if (!drFits(mNet, CAND, mBoxes, mN, IGN)) return false;
166	+  CUR.x = CAND.x; CUR.y = CAND.y; CUR.z = CAND.z; CUR.yaw = CAND.yaw;
167	+  return true;
168	+}
169	+/* Bước con kiểu xe đạp: trục sau đi sd theo hướng giữa bước, xe xoay sy; tâm = trục sau + AX theo hướng mới */
170	+function drTryArc(sd: number, sy: number): boolean {
171	+  const y0 = CUR.yaw, ym = y0 + sy / 2, y1 = y0 + sy;
172	+  const rx = CUR.x - AX * Math.cos(y0) + sd * Math.cos(ym), rz = CUR.z + AX * Math.sin(y0) - sd * Math.sin(ym);
173	+  CAND.x = rx + AX * Math.cos(y1); CAND.z = rz - AX * Math.sin(y1); CAND.yaw = y1;
174	+  return drTry();
175	+}
176	+function drTryShift(dx: number, dz: number): boolean {
177	+  CAND.x = CUR.x + dx; CAND.z = CUR.z + dz; CAND.yaw = CUR.yaw;
178	+  return drTry();
179	+}
180	+
181	+/* Dời thân xe từ p quãng dist (m, âm = lùi; quãng của trục sau) và xoay dyaw (rad), kết quả vào out (out có thể là p).
182	+   Chia bước con ≤ sim.sub (tính cả quãng góc xe quét khi xoay). Bước con bị chặn thì thử: chỉ tịnh tiến (bỏ xoay), chỉ thành phần X,
183	+   chỉ thành phần Z (trượt dọc vật cản thẳng trục); không được thì dừng. Trả phần quãng đã đi theo hướng định đi:
184	+   1 = trọn; trượt theo một trục tính bằng bình phương cos góc giữa trục đó và hướng định đi; 0 = đứng hẳn. */
185	+export function drMove(net: DrNet, p: DrPose, dist: number, dyaw: number, boxes: DrBox[], nBoxes: number, out: DrPose): number {
186	+  if (IGN.length < nBoxes) IGN = new Uint8Array(Math.max(nBoxes, IGN.length * 2));
187	+  const c0 = Math.cos(p.yaw), s0 = Math.sin(p.yaw);
188	+  for (let i = 0; i < nBoxes; i++) IGN[i] = drHitBox(boxes[i], p.x, p.y, p.z, c0, s0) ? 1 : 0;
189	+  mNet = net; mBoxes = boxes; mN = nBoxes;
190	+  CUR.x = p.x; CUR.y = p.y; CUR.z = p.z; CUR.yaw = p.yaw;
191	+  const n = Math.max(1, Math.ceil((Math.abs(dist) + Math.abs(dyaw) * REACH) / SIM.sub));
192	+  const sd = dist / n, sy = dyaw / n;
193	+  let done = 0;
194	+  for (let k = 0; k < n; k++) {
195	+    if (drTryArc(sd, sy)) { done += 1; continue; }
196	+    if (sd === 0) break;                                              // xoay tại chỗ bị chặn
197	+    if (sy !== 0 && drTryShift(sd * Math.cos(CUR.yaw), -sd * Math.sin(CUR.yaw))) { done += 1; continue; }
198	+    const tx = sd * Math.cos(CUR.yaw), tz = -sd * Math.sin(CUR.yaw);
199	+    if (Math.abs(tx) > EPS && drTryShift(tx, 0)) { done += tx * tx / (sd * sd); continue; }
200	+    if (Math.abs(tz) > EPS && drTryShift(0, tz)) { done += tz * tz / (sd * sd); continue; }
201	+    break;
202	+  }
203	+  out.x = CUR.x; out.y = CUR.y; out.z = CUR.z; out.yaw = CUR.yaw;
204	+  mNet = null; mBoxes = null;
205	+  return done / n;
206	+}
207	+
208	+/* ===== Đoạn thẳng (camera) ===== */
209	+/* Tham số t ∈ [0, 1] nơi đoạn a + t·d đi vào vật cản o (khối hộp / trụ đứng giữa y0..y1); 1 nếu không cắt; 0 nếu a ở trong */
210	+function drSegHit(o: DrSolid, ax: number, ay: number, az: number, dx: number, dy: number, dz: number): number {
211	+  let t0 = -Infinity, t1 = Infinity;
212	+  if (Math.abs(dy) < EPS) { if (ay < o.y0 || ay > o.y1) return 1; }
213	+  else { const a = (o.y0 - ay) / dy, b = (o.y1 - ay) / dy; t0 = a < b ? a : b; t1 = a < b ? b : a; }
214	+  if (o.kind === 'circle') {
215	+    const ox = ax - o.cx, oz = az - o.cz, A = dx * dx + dz * dz, B = 2 * (ox * dx + oz * dz), C = ox * ox + oz * oz - o.r * o.r;
216	+    if (A < EPS) { if (C > 0) return 1; }
217	+    else {
218	+      const D = B * B - 4 * A * C;
219	+      if (D < 0) return 1;
220	+      const q = Math.sqrt(D), a = (-B - q) / (2 * A), b = (-B + q) / (2 * A);
221	+      if (a > t0) t0 = a; if (b < t1) t1 = b;
222	+    }
223	+  } else {
224	+    if (Math.abs(dx) < EPS) { if (ax < o.x0 || ax > o.x1) return 1; }
225	+    else { const a = (o.x0 - ax) / dx, b = (o.x1 - ax) / dx; if (Math.min(a, b) > t0) t0 = Math.min(a, b); if (Math.max(a, b) < t1) t1 = Math.max(a, b); }
226	+    if (Math.abs(dz) < EPS) { if (az < o.z0 || az > o.z1) return 1; }
227	+    else { const a = (o.z0 - az) / dz, b = (o.z1 - az) / dz; if (Math.min(a, b) > t0) t0 = Math.min(a, b); if (Math.max(a, b) < t1) t1 = Math.max(a, b); }
228	+  }
229	+  if (t0 > t1 || t1 < 0 || t0 > 1) return 1;
230	+  return t0 > 0 ? t0 : 0;
231	+}
