233	+/* Phần đoạn thẳng a → b (0..1) đi được trước khi chạm vật cản (cùng khoảng cao độ, vì vật cản có y0..y1 tuyệt đối) */
234	+export function drSegClear(net: DrNet, ax: number, ay: number, az: number, bx: number, by: number, bz: number): number {
235	+  const g = drGrid(net), sol = net.solids, dx = bx - ax, dy = by - ay, dz = bz - az;
236	+  let t = 1;
237	+  const big = g.big;
238	+  for (let i = 0; i < big.length; i++) { const h = drSegHit(sol[big[i]], ax, ay, az, dx, dy, dz); if (h < t) t = h; }
239	+  const ix0 = Math.floor(Math.min(ax, bx) / DRC), ix1 = Math.floor(Math.max(ax, bx) / DRC);
240	+  const iz0 = Math.floor(Math.min(az, bz) / DRC), iz1 = Math.floor(Math.max(az, bz) / DRC);
241	+  for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
242	+    const list = g.cells.get(drKey(ix, iz));
243	+    if (!list) continue;
244	+    for (let i = 0; i < list.length; i++) { const h = drSegHit(sol[list[i]], ax, ay, az, dx, dy, dz); if (h < t) t = h; }
245	+  }
