254	+/* ============================ Lái xe: chuyển động theo số liệu VF 3 ============================
255	+   Mô hình "xe đạp" động học trên mặt bằng (spec §5.2): vị trí, hướng, tốc độ dọc có dấu, góc lái; không mô phỏng lốp, treo, trượt.
256	+   - Tăng tốc: a = a0 không đổi tới 50 km/h (a0 = 50 km/h / t50, qua đúng mốc thứ nhất), sau đó a = a0 · v50 / v · (1 − u^k)
257	+     với u = (v − v50) / (vMax − v50): giảm theo công suất không đổi và về 0 tại vMax. Số mũ k giải một lần (chia đôi) sao cho tới
258	+     99 % vMax (27,5 m/s ≈ 100 km/h, vì đường cong chỉ tiệm cận vMax) đúng t100.
259	+   - Lái: góc lái lớn nhất asin(wheelbase / turnRadius) (bán kính quay vòng tính ở tâm trục trước); tốc độ cao thì giới hạn thêm
260	+     sao cho gia tốc ngang v² · tan(góc) / wheelbase ≤ latMax. Góc lái tiến về đích theo steerRate, tự trả về 0 theo steerReturn
261	+     (cả hai là phần góc lái lớn nhất mỗi giây).
262	+   - Phanh / lùi: phanh khi đang tiến; |v| < sim.revV mà giữ phanh, không ga thì lùi dần tới reverseMax; đang lùi mà đạp ga thì phanh
263	+     về 0 rồi mới tiến. Nhả hết thì chậm dần theo coast, không tự lùi. Phanh tay hãm handBrake, không trượt. Dốc không đổi gia tốc.
264	+   - drStep chia dt thành bước ≤ sim.dt (tối đa sim.steps bước, phần dư bỏ); mỗi bước dời thân xe bằng drMove (collide.ts);
265	+     bị chặn thì v nhân phần quãng đã đi (đâm thẳng thì đứng hẳn, trượt dọc thì mất một phần).
266	+   Không cấp phát mỗi khung (D-018). Không import three. */
267	+import { CONFIG } from '../../config';
268	+import { drGround, type DrNet } from './net';
269	+import { drSpawnPose } from './roadData';
270	+import { drMove, type DrPose, type DrBox } from './collide';
271	+
272	+export interface DrState extends DrPose { pitch: number; v: number; steer: number; wheel: number; braking: boolean; evac: number }   // v: m/s có dấu; steer: rad; wheel: góc quay bánh tích lũy (rad)
273	+export interface DrInput { gas: number; brake: number; steer: number; hand: boolean }   // gas, brake: 0..1; steer: −1..1
274	+
275	+const CAR = CONFIG.drive.car, P = CONFIG.drive.perf, SIM = CONFIG.drive.sim;
276	+const L = CAR.wheelbase;
277	+const V50 = 50 / 3.6;                                                // m/s — mốc 0–50 km/h của t50
278	+const STEER_GEOM = Math.asin(L / P.turnRadius);                     // rad — góc lái lớn nhất theo hình học
279	+
280	+/* ===== Đường cong tăng tốc ===== */
281	+let A0 = NaN, KEXP = NaN;                                            // a0 (m/s²) và số mũ k, giải lười ở lần gọi đầu
282	+function drAccelK(v: number, k: number): number {
283	+  if (v <= V50) return A0;
284	+  if (v >= P.vMax) return 0;
285	+  const u = (v - V50) / (P.vMax - V50);
286	+  return A0 * V50 / v * (1 - Math.pow(u, k));
287	+}
288	+/* Thời gian 0 → 0,99 vMax với số mũ k (tích phân dv / a, điểm giữa) */
289	+function drT100(k: number): number {
290	+  const vt = 0.99 * P.vMax, N = 2000, h = (vt - V50) / N;
291	+  let t = V50 / A0;
292	+  for (let i = 0; i < N; i++) t += h / drAccelK(V50 + (i + 0.5) * h, k);
293	+  return t;
294	+}
295	+function drFitAccel(): void {
296	+  A0 = V50 / P.t50;
297	+  let lo = 0.2, hi = 50;                                             // k nhỏ ⇒ hãm sớm ⇒ chậm hơn: drT100 giảm theo k
298	+  for (let i = 0; i < 60; i++) { const m = (lo + hi) / 2; if (drT100(m) > P.t100) lo = m; else hi = m; }
299	+  KEXP = (lo + hi) / 2;
300	+}
301	+/* m/s² khi đạp hết ga ở tốc độ v ≥ 0 */
302	+export function drAccel(v: number): number {
303	+  if (Number.isNaN(KEXP)) drFitAccel();
304	+  return drAccelK(v, KEXP);
305	+}
306	+
307	+/* rad — góc lái lớn nhất ở tốc độ v (dấu bỏ qua) */
308	+export function drSteerMax(v: number): number {
309	+  const a = Math.abs(v);
310	+  if (a < 1e-6) return STEER_GEOM;
311	+  const lim = Math.atan(L * P.latMax / (a * a));
312	+  return lim < STEER_GEOM ? lim : STEER_GEOM;
313	+}
314	+
315	+const drToward0 = (v: number, d: number): number => v > 0 ? (v > d ? v - d : 0) : (v < -d ? v + d : 0);
316	+
317	+/* Dốc dọc từ cao độ mặt đường tại trục trước / sau; giữ giá trị cũ nếu một trục không có mặt đường cùng tầng */
318	+function drPitch(s: DrState, net: DrNet): void {
319	+  const fx = Math.cos(s.yaw) * L / 2, fz = -Math.sin(s.yaw) * L / 2;
320	+  const yf = drGround(net, s.x + fx, s.z + fz, s.y), yr = drGround(net, s.x - fx, s.z - fz, s.y);
321	+  if (!Number.isNaN(yf) && !Number.isNaN(yr)) s.pitch = Math.atan2(yf - yr, L);
322	+}
323	+
324	+/* Xe mới ở chỗ xuất phát của slot, đứng yên trên mặt đường cao nhất tại đó (mặt cầu) */
325	+export function drCreate(net: DrNet, slot: number): DrState {
326	+  const sp = drSpawnPose(slot);
327	+  let y = -Infinity;
328	+  for (const p of net.pads) {
329	+    if (sp.x < p.x0 || sp.x > p.x1 || sp.z < p.z0 || sp.z > p.z1) continue;
330	+    if (p.gate !== undefined && net.closed.has(p.gate)) continue;
331	+    y = Math.max(y, p.y(sp.x, sp.z));
332	+  }
333	+  const s: DrState = { x: sp.x, y: Number.isFinite(y) ? y : CONFIG.roadY, z: sp.z, yaw: sp.yaw, pitch: 0, v: 0, steer: 0, wheel: 0, braking: false, evac: 0 };
334	+  drPitch(s, net);
335	+  return s;
336	+}
337	+
338	+const MOVED: DrPose = { x: 0, y: 0, z: 0, yaw: 0 };
339	+
340	+/* Một bước h ≤ sim.dt */
341	+function drStep1(s: DrState, inp: DrInput, net: DrNet, boxes: DrBox[], nBoxes: number, h: number): void {
342	+  const g = inp.gas > 0 ? (inp.gas < 1 ? inp.gas : 1) : 0, b = inp.brake > 0 ? (inp.brake < 1 ? inp.brake : 1) : 0;
343	+  let v = s.v, braking = false;
344	+  /* tốc độ */
345	+  if (inp.hand) { v = drToward0(v, P.handBrake * h); braking = true; }
346	+  else if (b > 0 && g === 0) {
347	+    if (v >= SIM.revV) { v = Math.max(0, v - b * P.brake * h); braking = true; }                       // đang tiến: phanh
348	+    else v = Math.max(-P.reverseMax, v - b * (v > 0 ? P.brake : drAccel(-v)) * h);                   // gần đứng / đang lùi: lùi dần
349	+  } else if (g > 0 && b === 0) {
350	+    if (v < 0) { v = Math.min(0, v + g * P.brake * h); braking = true; }                             // đang lùi: phanh về 0 rồi mới tiến
351	+    else v = Math.min(P.vMax, v + g * drAccel(v) * h);
352	+  } else if (g > 0 && b > 0) { v = drToward0(v, b * P.brake * h); braking = true; }
353	+  else v = drToward0(v, P.coast * h);
354	+  /* góc lái */
355	+  const lim = drSteerMax(v), want = inp.steer > 1 ? 1 : inp.steer < -1 ? -1 : inp.steer;
356	+  let st = s.steer;
357	+  if (want === 0) st = drToward0(st, P.steerReturn * STEER_GEOM * h);
358	+  else {
359	+    const tgt = want * lim, back = Math.abs(tgt) < Math.abs(st) || tgt * st < 0;
360	+    const d = (back ? Math.max(P.steerRate, P.steerReturn) : P.steerRate) * STEER_GEOM * h;
361	+    st = st < tgt ? Math.min(tgt, st + d) : Math.max(tgt, st - d);
362	+  }
363	+  if (st > lim) st = lim; else if (st < -lim) st = -lim;
364	+  /* dời thân xe */
365	+  const dist = v * h, f = drMove(net, s, dist, dist * Math.tan(st) / L, boxes, nBoxes, MOVED);
366	+  s.x = MOVED.x; s.y = MOVED.y; s.z = MOVED.z; s.yaw = MOVED.yaw;
367	+  if (f < 1) v *= f;
368	+  s.v = v; s.steer = st; s.braking = braking;
369	+  s.wheel += dist * f / (CAR.wheelDia / 2);
370	+  drPitch(s, net);
371	+}
372	+
373	+/* Bước mô phỏng cho khung dài dt (s) */
374	+export function drStep(s: DrState, inp: DrInput, net: DrNet, boxes: DrBox[], nBoxes: number, dt: number): void {
375	+  let rem = dt;
376	+  for (let k = 0; k < SIM.steps && rem > 1e-6; k++) {
377	+    const h = rem < SIM.dt ? rem : SIM.dt;
378	+    drStep1(s, inp, net, boxes, nBoxes, h);
379	+    rem -= h;
380	+  }
381	+}
